internal val LOCALE_DISPLAY_NAMES_BO: String =
    "root\u001Fbn\u001Dབྷང་ག་ལའི་སྐད།\u001Ebo\u001Dབོད་སྐད་\u001Eda\u001Dཏེན་མག་གི་སྐད།\u001Ede\u001Dའཇར་མན་གྱི།\u001Edz\u001Dརྫོང་ཁ\u001Een\u001Dདབྱིན་ཇིའི་སྐད།\u001Een_CA\u001Dདབྱིན་ཇིའི་སྐད། (ཁེ་ན་ཌ་)\u001Een_GB\u001Dདབྱིན་ཇིའི་སྐད། (དབྱིན་ལན་)\u001Een_US\u001Dདབྱིན་ཇིའི་སྐད། (ཨ་རི་)\u001Ees\u001Dཞི་པན་ཡའི།\u001Efr\u001Dཧྥ་རན་སིའི་།\u001Egaa\u001Dགཱ་སྐད།\u001Egu\u001Dགུཇ་རཱཏི་སྐད།\u001Ehi\u001Dཧིན་དི\u001Eid\u001Dཨིན་དོ་ནི་སི་སྐད།\u001Eit\u001Dདབྱི་ཏ་་ལའི་མི།\u001Eja\u001Dཉི་ཧོང་སྐད་\u001Ekn\u001Dཀནྣ་ཌ་སྐད།\u001Eko\u001Dཁོ་རེ་ཡའི་སྐད།\u001Ela\u001Dལཱ་ཏིན་སྐད།\u001Emn\u001Dསོག་སྐད།\u001Emr\u001Dམ་ར་ཐི་སྐད།\u001Ems\u001Dམ་ལ་ཡ་སྐད།\u001Emy\u001Dའབར་མའི་སྐད།\u001Ene\u001Dནེ་པ་ལི\u001Enl\u001Dཧའོ་ལན་སྐད།\u001Enn\u001Dནོ་ཝེ་སྐད།\u001Eor\u001Dཨཽ་རི་ཡ་སྐད།\u001Epl\u001Dཔོ་ལན་སྐད།\u001Ept\u001Dཕི་ཐོ་ཡའི།\u001Ept_BR\u001Dཔ་ཞའི་མི། ཕི་ཐོ་ཡའི་མི།\u001Eru\u001Dཨུ་རུ་སུ་སྐད་\u001Esa\u001Dསཾ་སྐྲྀ་ཏ།\u001Esi\u001Dཞི་ལན་སྐད།\u001Esv\u001Dཧྲུའི་ཏན་སྐད།\u001Eta\u001Dཏཱ་མིལ་སྐད།\u001Ete\u001Dཏེ་ལུ་གུ་སྐད།\u001Eth\u001Dཐའའི་ཡུལ་སྐད།\u001Etr\u001Dཐུར་ཁེའི་སྐད།\u001Eug\u001Dཡུ་གུར་སྐད།\u001Euk\u001Dཡུ་ཀྲ་ནི་སྐད།\u001Eund\u001Dམིའི་ཤེས་རྟོགས་མ་བྱུང་བ། ཡང་ན་ཆད་ལྷག་ཅན་གྱི་སྐད་བརྡ།\u001Eur\u001Dཝུའུ་ཏུའུ་སྐད།\u001Evi\u001Dཡོ་ནན་སྐད།\u001Ezen\u001Dཟེ་ན་གཱ་སྐད།\u001Ezh\u001Dརྒྱ་སྐད་\u001Ezh_Hans\u001Dསྟབས་བརྡའི། ཀྲུང་གོའི།\u001Ezh_Hant\u001Dསྲོལ་རྒྱུན་གྱི།\u001Ezu\u001Dཟུ་ལུ་སྐད།\u001Ezun\u001Dཟུ་ནི་སྐད།\u001Ezza\u001Dཟ་ཟའ་སྐད།\u001FArab\u001Dའ་ལ་པོའི་སྐད་ཡིག་།\u001ECyrl\u001Dགོ་སའི་ལ་ཧྥུ་སྐད་ཡིག་།\u001EDeva\u001Dདེ་བ་ནཱ་ག་རཱི་སྐད་ཡིག\u001EGujr\u001Dགུཇ་རཱཏི་སྐད།\u001EHans\u001Dརྒྱ་ཡིག་གསར་པ།\u001EHant\u001Dརྒྱ་ཡིག་རྙིང་པ།\u001ELatn\u001Dལ་ཏིན་སྐད་ཡིག་།\u001EMymr\u001Dའབར་མའི་སྐད་ཡིག\u001ETibt\u001Dབོད་ཡིག་\u001EZxxx\u001Dསྙན་བརྒྱུད། ཡིག་རིགས་སུ་མ་བཀོད་པའི་ཟིན་ཐོ།\u001EZzzz\u001Dམིའི་ཤེས་རྟོགས་མ་བྱུང་བ། ཡང་ན་ཆད་ལྷག་ཅན་གྱི་ཟིན་བྲིས།\u001F001\u001Dའཛམ་གླིང་།\u001E002\u001Dཨཕྲི་ཀ།\u001E053\u001Dཨསྟྲེ་ལི་ཡ་དང་། ནིའུ་ཛི་ལན྄ཌ།\u001E142\u001Dཨེ་ཤི་ཡ།\u001E150\u001Dཡུ་རོབ།\u001EAD\u001Dཨེན་ཌོ་ར།\u001EAE\u001Dཨ་རབ། ཨི་མི་རཊ྄། ཆིག་སྒྲིལ་རྒྱལ་ཁབ།\u001EAF\u001Dཨཕ་ག་ནི་སྟཱན།\u001EAG\u001Dཨེན་ཊི་གུ་དང་། བྷར་བུ་ཌ།\u001EAI\u001Dཨང་གུའི་ལ།\u001EAL\u001Dཨལ་བཱ་ནི་ཡ།\u001EAM\u001Dཨར་མེ་ནི་ཡ།\u001EAO\u001Dཨང་གཽ་ལ།\u001EAQ\u001Dལྷོ་རྩེའི་མཐའ་གླིང་།\u001EAR\u001Dཨར་ཇེན་ཊི་ན།\u001EAT\u001Dཨསྟྲི་ཡ།\u001EAU\u001Dཨསྟྲེ་ལི་ཡ།\u001EAW\u001Dཨ་རུ་བ།\u001EAZ\u001Dཨཛར་བཡེ་ཇན།\u001EBA\u001Dབོསྣི་ཡ་དང་ཧརྫོ་གོ་ཝི་ན།\u001EBB\u001Dབཱརྦ་ཌོས྄།\u001EBD\u001Dབངྒ་ལ་དེཤ།\u001EBE\u001Dབེལ་ཇི་ཡམ།\u001EBF\u001Dབརཀི་ན། ཕསོ།\u001EBG\u001Dབུལ་ག་རི་ཡ།\u001EBH\u001Dབྷཱ་རེན།\u001EBI\u001Dབུ་རུན་ཌི།\u001EBJ\u001Dབཱེ་ནིན།\u001EBM\u001Dབར་མུ་ཌ།\u001EBN\u001Dབུ་རུ་ནེ།\u001EBO\u001Dབོ་ལི་ཝིཡ།\u001EBR\u001Dབ་རཱ་ཛིལ།\u001EBS\u001Dབྷཱ་མས྄།\u001EBT\u001Dའབྲུག་ཡུལ།\u001EBW\u001Dབོཙ་ཝ་ན།\u001EBY\u001Dབེ་ལུ་རུ་སུ།\u001EBZ\u001Dབེ་ལིཛ།\u001ECA\u001Dཁེ་ན་ཌ།\u001ECH\u001Dཧྲུད་ཧྲི།\u001ECI\u001Dཀོ་ཊེ་ཌི། ཨི་ཝོ་རེ།\u001ECK\u001Dཀཱུག གླིང་ཕྲེན་རྒྱལ་ཁབ།\u001ECL\u001Dཅི་ལི།\u001ECM\u001Dཀ་མེ་རུན།\u001ECN\u001Dརྒྱ་ནག\u001ECO\u001Dཀོ་ལོམ་བི་ཡ།\u001ECR\u001Dཀོ་ས྄ཊ་རི་ཀ།\u001ECU\u001Dཁྱུའུ་བ།\u001ECY\u001Dསཱཡེ་པ་རས྄།\u001ECZ\u001Dཅཻག་སྤྱི་མཐུན་རྒྱལ་ཁབ།\u001EDE\u001Dའཇར་མན་\u001EDJ\u001Dཛི་བུ་ཏི།\u001EDK\u001Dཌེན་མཱརྐ།\u001EDM\u001Dཌོ་མིན་ནི་ཀ།\u001EDO\u001Dཌོ་མིནནི་ཀན་སྤྱི་མཐུན་རྒྱལ་ཁབ།\u001EDZ\u001Dཨལ་ཇི་རི་ཡ།\u001EEC\u001Dཨི་ཁྭ་ཌོར།\u001EEE\u001Dཨིསྟོ་ནི་ཡ།\u001EEG\u001Dཨི་ཇིབྚ།\u001EER\u001Dཨེ་རི་ཏྲེ་ཨ།\u001EES\u001Dསི་པན།\u001EET\u001Dཨི་ཐིའོ་པི་ཡ།\u001EFI\u001Dཕིན་ལན྄ཌ།\u001EFJ\u001Dཕི་ཇི།\u001EFK\u001Dཕལྐ་ལནྜ་གླིང་ཕྲན།\u001EFR\u001Dཕ་རཱན་སི།\u001EGA\u001Dགེ་བཽན།\u001EGB\u001Dདབྱིན་ཇི་\u001EGD\u001Dགྷ་རི་ན་ཌ།\u001EGE\u001Dཇོར་ཇི་ཡ།\u001EGH\u001Dགྷ་ན།\u001EGI\u001Dཇིབ་རཱལ་ཊར།\u001EGM\u001Dགྷམ་བི་ཡ།\u001EGN\u001Dགྷི་ནི་ཡ།\u001EGR\u001Dགྷི་རཱི་སི།\u001EGT\u001Dགྷོ་ཊེ་མ་ལ།\u001EGW\u001Dགྷི་ནི་ཡ་བིས྄་སོ།\u001EGY\u001Dགྷུ་ཡཱ་ན།\u001EHK\u001Dཧོང་ཀོང༌།\u001EHN\u001Dཧོན་དུ་རས྄།\u001EHR\u001Dཀུརོ་ཤི་ཡ།\u001EHT\u001Dཧེ་ཏི།\u001EHU\u001Dཧངྒ་རི།\u001EID\u001Dཨིན་ཌོ་ནེ་ཤི་ཡ།\u001EIE\u001Dཨ་ཡར་ལནཌ།\u001EIL\u001Dཨི་ཛ྄་རེལ།\u001EIN\u001Dརྒྱ་གར་\u001EIQ\u001Dཨི་རག།\u001EIR\u001Dཨི་རཱན།\u001EIS\u001Dཨ་ཨི་སི་ལནད།\u001EIT\u001Dཨི་ཀྲར་ལི་\u001EJM\u001Dཛ་མེ་ཀ།\u001EJO\u001Dཇོར་ཌན།\u001EJP\u001Dཉི་ཧོང་\u001EKE\u001Dཁེན་ཉི་ཡ།\u001EKG\u001Dཁིར་གིཛ་སྟཱན།\u001EKH\u001Dཀམ་བོ་ཌི་ཡ།\u001EKI\u001Dཀི་རི་བཱ་ཏི།\u001EKN\u001Dསེནྚ། ཀིཊྚས྄། དང༌། ནེ་བིས྄།\u001EKR\u001Dལྷོ་ཀོ་རི་ཡ།\u001EKW\u001Dཀུ་ཝེད་རྒྱལ་ཁབ།\u001EKY\u001Dཁེ་མེན་གླིང་ཕྲན།\u001EKZ\u001Dཁ་ཛཱག་སྟཱན།\u001ELA\u001Dལཱ་འོས།\u001ELB\u001Dལེབ་ནོན།\u001ELC\u001Dསེནྚ། ལུ་ཤི་ཡ།\u001ELI\u001Dལེག་ཏེན་ཚིན།\u001ELK\u001Dཤྲཱི་ལངྐ་།\u001ELR\u001Dལི་བེ་རི་ཡ།\u001ELS\u001Dལེ་སོ་ཐོ།\u001ELT\u001Dལི་ཐུ་ཨེ་ནི་ཡ།\u001ELU\u001Dལཀ་ཛམ་བོརྒ།\u001ELV\u001Dལཏ་བི་ཡ།\u001ELY\u001Dལི་བི་ཡ།\u001EMA\u001Dམོ་རོ་ཀྐོ།\u001EMC\u001Dམོ་ན་ཀོ།\u001EMG\u001Dམ་དཱ་གྷསྐཱར།\u001EMH\u001Dམཱར་ཤལ་གླིང་ཕྲེན།\u001EML\u001Dམ་ལི།\u001EMM\u001Dའབར་མ།\u001EMN\u001Dསོག་ཡུལ།\u001EMO\u001Dམེ་ཀའོ།\u001EMR\u001Dམཽ་རི་ཏ་ནི་ཡ།\u001EMT\u001Dམལ་ཊ།\u001EMU\u001Dམཽ་རིཤས྄།\u001EMV\u001Dམལ་དྭིབ།\u001EMW\u001Dམཱ་ལཱ་ཝི།\u001EMX\u001Dམེཀ་སི་ཀོ།\u001EMY\u001Dམ་ལེ་ཤི་ཡ།\u001EMZ\u001Dམོ་ཛམ་བིག།\u001ENA\u001Dན་མི་བི་ཡ།\u001ENE\u001Dནའི་ཇར།\u001ENG\u001Dནཱའི་ཇི་རི་ཡ།\u001ENI\u001Dནི་ཀ་ར་གུ་ཨ།\u001ENL\u001Dཧའོ་ལན།\u001ENO\u001Dནོར་ཝེ།\u001ENP\u001Dབལ་ཡུལ་\u001ENR\u001Dནཽ་རུ།\u001ENU\u001Dནིའུ་ཝ།\u001ENZ\u001Dནིའུ་ཛི་ལན྄ཌ།\u001EOM\u001Dཨོ་མན།\u001EPA\u001Dཔ་ནཱ་མ།\u001EPE\u001Dཔེ་རུ།\u001EPG\u001Dཔ་པུ་ཨ། ནིའུ། གྷི་ནི།\u001EPH\u001Dཕི་ལི་པིནས྄།\u001EPK\u001Dཔཀི་སྟཱན།\u001EPL\u001Dཔོ་ལནྜ།\u001EPT\u001Dཔོར་ཏུ་གྷལ།\u001EPW\u001Dཔ་ལཽ།\u001EPY\u001Dཔཱ་ར་གེ།\u001EQA\u001Dཀ་ཏཱར།\u001ERO\u001Dརོ་མཱ་ནིཡ།\u001ERS\u001Dསེར་བི་ཡ།\u001ERU\u001Dཨུ་རུ་སུ་\u001ERW\u001Dརུ་ཝན་ཌ།\u001ESA\u001Dསཽ་དྷི་ཨ་རཱ་བི་ཡ།\u001ESB\u001Dསོ་ལོ་མོན། གླིང་ཕྲན་ཚོ་ཁག།\u001ESC\u001Dསཱ་ཤཻལ།\u001ESD\u001Dསུ་དཱན།\u001ESE\u001Dཧྲུའི་ཏན།\u001ESG\u001Dསིངྒ་པུར།\u001ESH\u001Dསེནྚ། ཧེ་ལི་ན།\u001ESI\u001Dས་ལཽ་ཝེ་ནི་ཡ།\u001ESK\u001Dས་ལཽ་ཝཀྱ།\u001ESL\u001Dསེ་ཡར་ར། ལིའོན།\u001ESM\u001Dསན་མེ་རི་ནོ།\u001ESN\u001Dསེ་ནི་གྷལ།\u001ESO\u001Dསོ་མཱལི་ཡ།\u001ESR\u001Dསུ་རི་ནཱམ།\u001EST\u001Dས